      "card_ids": ["C03"],
      "claim": "AH-7921 achieved a brain-to-plasma ratio of 16.6 in rats, demonstrating that this chemical space can produce high CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Compound 9e showed high brain exposure (1100 ng/g brain vs 650 ng/mL plasma) and was summarized as having excellent CNS exposure in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "L655,708 had a 59% brain uptake index in rats, a direct first-pass extraction measure indicating reasonable delivery to the brain.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer experimental records consistently demonstrate BBB/CNS penetration in rats, monkeys, or humans, including direct brain:plasma, CSF, PET, and brain uptake measurements; therefore the query is predicted to have meaningful CNS access.",
